// Package stateui is a JSX target for the client-state golden cases. It
// implements the JSX contract by delegating to github.com/vuka-lang/ui/v2 and
// adds ui's state API in the shape the compiler lowers to; a binding renders
// as its initial value plus data-vk-b-<name>="<expression> <deps>", and a
// state as <file>:<line>=<value>, enough to see what the compiler wrote.
package stateui

import (
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"reflect"
	"runtime"
	"slices"
	"sort"
	"strconv"
	"strings"

	ui "github.com/vuka-lang/ui/v2"
)

// VukaJSX marks this package as a JSX target implementing version 3.
const VukaJSX = 3

// VukaState names the package client state lowers to.
const VukaState = "vukatest.local/stateui/uigen"

type (
	Node = ui.Node
	Attr = ui.Attr
)

func El(tag string, attrs []Attr, children ...Node) Node {
	var out []Attr
	for _, a := range attrs {
		out = append(out, attrOf(a.Name, a.Value)...)
	}
	return ui.El(tag, out, children...)
}

// attrOf is an attribute as the page shows it: a binding as its value and
// its expression, commands as data-vk-js-<event>.
func attrOf(name string, v any) []Attr {
	if s, ok := v.(AnyState); ok {
		v = s.binding()
	}
	if c, ok := v.(Classes); ok {
		v = c.binding()
	}
	switch v := v.(type) {
	case Binding:
		return []Attr{{Name: name, Value: classText(v.Init)}, {Name: "data-vk-b-" + strings.ToLower(name), Value: v.String()}}
	case Commands:
		return []Attr{{Name: "data-vk-js-" + strings.ToLower(strings.TrimPrefix(name, "on")), Value: v.String()}}
	}
	if strings.HasPrefix(name, "on") && reflect.TypeOf(v) != nil && reflect.TypeOf(v).Kind() == reflect.Func {
		v = ui.On(v)
	}
	return []Attr{{Name: name, Value: classText(v)}}
}

func Child(v any) Node {
	if s, ok := v.(AnyState); ok {
		v = s.binding()
	}
	if b, ok := v.(Binding); ok {
		return ui.El("vk-t", []Attr{{Name: "data-vk-b", Value: b.String()}}, ui.Text(b.Init))
	}
	if n := mountOf(v); n != nil {
		return n
	}
	return ui.Child(v)
}

func Fragment(children ...Node) Node { return ui.Fragment(children...) }
func Try(n Node, err error) Node     { return ui.Try(n, err) }
func On(fn any) any {
	if c, ok := fn.(Commands); ok {
		return c
	}
	return ui.On(fn)
}

func String(ctx context.Context, n Node) (string, error) { return ui.String(ctx, n) }

// HTML is ui's, its attribute holes written as attribute sets so a binding
// can write two attributes.
func HTML(src string, args ...any) Node {
	var labels []string
	attrs := map[int]string{}
	var b strings.Builder
	for i := 0; i < len(src); i++ {
		if src[i] != '{' || strings.HasPrefix(src[i:], "{{") {
			b.WriteByte(src[i])
			continue
		}
		end := holeEnd(src, i+1)
		label := strings.TrimSuffix(src[i+1:end], "...")
		n := slices.Index(labels, label)
		if n < 0 {
			n, labels = len(labels), append(labels, label)
		}
		out := b.String()
		if k := strings.LastIndexAny(out, " \n\t"); k >= 0 && strings.HasSuffix(out, "=") {
			name := out[k+1 : len(out)-1]
			if name != "key" && !strings.HasPrefix(name, "class:") {
				attrs[n] = name
				b.Reset()
				b.WriteString(out[:k+1] + "{" + label + "...}")
				i = end
				continue
			}
		}
		b.WriteString(src[i : end+1])
		i = end
	}
	out := make([]any, len(args))
	for i, a := range args {
		if name, ok := attrs[i]; ok {
			out[i] = attrOf(name, a)
			continue
		}
		switch a := a.(type) {
		case []Attr:
			var set []Attr
			for _, x := range a {
				set = append(set, attrOf(x.Name, x.Value)...)
			}
			out[i] = set
		case AnyState, Binding:
			out[i] = Child(a)
		default:
			if n := mountOf(a); n != nil {
				out[i] = n
			} else {
				out[i] = a
			}
		}
	}
	return ui.HTML(b.String(), out...)
}

// holeEnd is the } closing the hole whose label starts at i.
func holeEnd(s string, i int) int {
	depth := 0
	for ; i < len(s); i++ {
		switch c := s[i]; c {
		case '"', '`':
			for i++; i < len(s) && s[i] != c; i++ {
				if s[i] == '\\' && c == '"' {
					i++
				}
			}
		case '{', '(', '[':
			depth++
		case ')', ']':
			depth--
		case '}':
			if depth == 0 {
				return i
			}
			depth--
		}
	}
	return len(s) - 1
}

type cell struct {
	site string
	v    any
}

// State is a state: its cell, the field path in it, the value it renders
// with; a derived one is its expression instead.
type State[T any] struct {
	c    *cell
	path []string
	v    T
	x    *expr
}

// expr is an operation over states and values.
type expr struct {
	op   string
	args []any
}

var sites = map[string]int{}

// site is the file and line UseState is called from, numbered after the
// first on a line; a package's variable's is the package's.
func site() string {
	_, file, line, _ := runtime.Caller(3)
	s := filepath.Base(file) + ":" + strconv.Itoa(line)
	if file == "<autogenerated>" {
		s = "pkg"
	}
	if sites[s]++; sites[s] > 1 {
		s += "." + strconv.Itoa(sites[s])
	}
	return s
}

// GenState is a state declared where uigen's caller calls it, the page's
// when page; or at site when it isn't "".
func GenState[T any](site_ string, page bool, initial T) State[T] {
	if site_ == "" {
		site_ = site()
	}
	if page {
		site_ = "g:" + site_
	}
	return State[T]{c: &cell{site_, initial}, v: initial}
}

func GenDerived[T any](value T) State[T] { return State[T]{v: value, x: &expr{"", []any{value}}} }

func GenAt[T, S any](s State[S], path string) State[T] {
	v := reflect.ValueOf(s.v)
	for _, name := range strings.Split(path, ".") {
		v = v.FieldByName(name)
	}
	return State[T]{c: s.c, path: append(s.path[:len(s.path):len(s.path)], strings.Split(path, ".")...), v: v.Interface().(T)}
}

func derive[T, R any](s State[T], v R, op string, args ...any) State[R] {
	return State[R]{v: v, x: &expr{op, append([]any{s}, args...)}}
}

func val(o any) any {
	if s, ok := o.(AnyState); ok {
		return s.value()
	}
	return o
}

func (s State[T]) GenNot() State[bool] { return derive(s, !any(s.v).(bool), "!") }
func (s State[T]) GenNeg() State[T]    { return derive(s, arith(s.v, s.v, -2).(T), "neg") }
func (s State[T]) GenLen() State[int]  { return derive(s, reflect.ValueOf(s.v).Len(), "len") }
func (s State[T]) GenAnd(o any) State[bool] {
	return derive(s, any(s.v).(bool) && val(o).(bool), "&&", o)
}
func (s State[T]) GenOr(o any) State[bool] {
	return derive(s, any(s.v).(bool) || val(o).(bool), "||", o)
}
func (s State[T]) GenEq(o any) State[bool]       { return derive(s, cmp(s.v, val(o)) == 0, "==", o) }
func (s State[T]) GenNe(o any) State[bool]       { return derive(s, cmp(s.v, val(o)) != 0, "!=", o) }
func (s State[T]) GenLt(o any) State[bool]       { return derive(s, cmp(s.v, val(o)) < 0, "<", o) }
func (s State[T]) GenLe(o any) State[bool]       { return derive(s, cmp(s.v, val(o)) <= 0, "<=", o) }
func (s State[T]) GenGt(o any) State[bool]       { return derive(s, cmp(s.v, val(o)) > 0, ">", o) }
func (s State[T]) GenGe(o any) State[bool]       { return derive(s, cmp(s.v, val(o)) >= 0, ">=", o) }
func (s State[T]) GenPlus(o any) State[T]        { return derive(s, arith(s.v, val(o), 1).(T), "+", o) }
func (s State[T]) GenMinus(o any) State[T]       { return derive(s, arith(s.v, val(o), -1).(T), "-", o) }
func (s State[T]) Get() T                        { return s.v }
func (s State[T]) Set(v T) Commands              { return JS.Set(s, v) }
func (s State[T]) GenToggle(c Commands) Commands { return c.add("toggle " + s.String()) }
func (s State[T]) GenInc(c Commands) Commands    { return c.add("inc " + s.String()) }
func (s State[T]) GenDec(c Commands) Commands    { return c.add("dec " + s.String()) }

// Zero reports whether s was never declared: a field uigen.States names.
func (s State[T]) Zero() bool { return s.c == nil && s.x == nil }

// Named is a state of s's type declared as the field name.
func (s State[T]) Named(name string) any {
	var v T
	return State[T]{c: &cell{"field " + name, v}, v: v}
}

func (s State[T]) anyState() string               { return s.String() }
func (s State[T]) value() any                     { return s.v }
func (s State[T]) node() (*expr, *cell, []string) { return s.x, s.c, s.path }

// binding is the state as an expression the page shows: a derived one's
// own, a state's read.
func (s State[T]) binding() Binding {
	b := Binding{Init: s.v}
	var deps []any
	var m strings.Builder
	enc := json.NewEncoder(&m)
	enc.SetEscapeHTML(false)
	enc.Encode(b.json(s, &deps))
	b.Expr, b.Deps = strings.TrimSpace(m.String()), deps
	return b
}

func (s State[T]) String() string {
	if s.x != nil {
		return "(" + s.binding().String() + ")"
	}
	return s.c.site + strings.Join(append([]string{""}, s.path...), ".") + "=" + fmt.Sprint(s.v)
}

// cmp orders numbers and strings, and tells other values equal or not.
func cmp(a, b any) int {
	av, bv := reflect.ValueOf(a), reflect.ValueOf(b)
	switch {
	case av.CanInt() || av.CanFloat():
		x, y := num(av), num(bv)
		if x < y {
			return -1
		} else if x > y {
			return 1
		}
		return 0
	case av.Kind() == reflect.String:
		return strings.Compare(av.String(), bv.String())
	}
	if a == b {
		return 0
	}
	return 1
}

func num(v reflect.Value) float64 {
	if v.CanInt() {
		return float64(v.Int())
	}
	return v.Float()
}

// arith is a + b (sign 1), a - b (-1) or -a (-2), as a's type.
func arith(a, b any, sign int) any {
	av := reflect.ValueOf(a)
	r := reflect.New(av.Type()).Elem()
	switch {
	case av.Kind() == reflect.String:
		r.SetString(av.String() + reflect.ValueOf(b).String())
	case av.CanInt():
		x, y := av.Int(), int64(num(reflect.ValueOf(b)))
		r.SetInt(map[int]int64{1: x + y, -1: x - y, -2: -x}[sign])
	default:
		x, y := av.Float(), num(reflect.ValueOf(b))
		r.SetFloat(map[int]float64{1: x + y, -1: x - y, -2: -x}[sign])
	}
	return r.Interface()
}

type AnyState interface {
	anyState() string
	value() any
	binding() Binding
	node() (*expr, *cell, []string)
}

// BindAttr is an attribute named name bound to state s.
func BindAttr(name string, s AnyState) Attr { return Attr{Name: name, Value: s.binding()} }

type Commands struct{ ops []string }

var JS Commands

func (c Commands) add(op string) Commands { return Commands{append(c.ops[:len(c.ops):len(c.ops)], op)} }
func (c Commands) Set(s AnyState, v any) Commands {
	return c.add("set " + s.anyState() + " " + fmt.Sprint(v))
}
func (c Commands) Push(h any) Commands { return c.add("push") }
func (c Commands) String() string      { return strings.Join(c.ops, "; ") }

type Binding struct {
	Init any
	Expr string
	Deps []any
}

// json is x's expression: a state read {"$": i}, with "p" for a field's
// path, its dep the state; a derived one's operation; a value inline.
func (Binding) json(x any, deps *[]any) any {
	s, ok := x.(AnyState)
	if !ok {
		return x
	}
	ex, c, path := s.node()
	if ex != nil {
		if ex.op == "" {
			return ex.args[0]
		}
		out := []any{ex.op}
		for _, a := range ex.args {
			if m, ok := a.(map[string]any); ok {
				obj := map[string]any{}
				for k, v := range m {
					obj[k] = Binding{}.json(v, deps)
				}
				out = append(out, obj)
				continue
			}
			out = append(out, Binding{}.json(a, deps))
		}
		return out
	}
	i := -1
	for j, d := range *deps {
		if _, dc, _ := d.(AnyState).node(); dc == c {
			i = j
		}
	}
	if i < 0 {
		i = len(*deps)
		*deps = append(*deps, base{c})
	}
	r := map[string]any{"$": i}
	if len(path) > 0 {
		r["p"] = path
	}
	return r
}

// base is a field's state, as a dep.
type base struct{ c *cell }

func (b base) anyState() string               { return b.c.site }
func (b base) value() any                     { return nil }
func (b base) binding() Binding               { return Binding{} }
func (b base) node() (*expr, *cell, []string) { return nil, b.c, nil }
func (b base) String() string                 { return b.c.site + "=" + fmt.Sprint(b.c.v) }

func (b Binding) String() string {
	var ds []string
	for _, d := range b.Deps {
		ds = append(ds, fmt.Sprint(d))
	}
	return b.Expr + " " + strings.Join(ds, " ")
}

type Class map[string]bool

type Classes map[string]any

func (c Classes) binding() Binding {
	init := Class{}
	m := map[string]any{}
	for k, v := range c {
		init[k], _ = val(v).(bool)
		m[k] = v
	}
	s := State[Class]{v: init, x: &expr{"class", []any{m}}}
	return s.binding()
}

type ShowProps struct {
	When     any
	Children Node
}

func Show(p ShowProps) Node {
	w := p.When
	if s, ok := w.(AnyState); ok {
		if ex, _, _ := s.node(); ex != nil {
			w = s.binding()
		}
	}
	return ui.El("vk-show", []Attr{{Name: "data-vk-show", Value: fmt.Sprint(w)}}, p.Children)
}

// classText is a Class as its attribute's text; other values as they are.
func classText(v any) any {
	c, ok := v.(Class)
	if !ok {
		return v
	}
	var on []string
	for k, v := range c {
		if v {
			on = append(on, k)
		}
	}
	sort.Strings(on)
	return strings.Join(on, " ")
}
